import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the simple moving averages
    sma_4 = df['close'].rolling(window=4).mean()
    sma_35 = df['close'].rolling(window=35).mean()

    # Initialize the signals series
    signals = pd.Series(0, index=df.index)

    # Iterate over the DataFrame
    for i in range(len(sma_4)):
        if i >= 34:  # Ensure we have enough data for SMA(35)
            if sma_4[i] > sma_35[i]:
                signals[i] = 1
            elif sma_4[i] <= sma_35[i]:
                signals[i] = 0

    return signals

