def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the RSI for RSI(16)
    df['RSI_16'] = df['close'].pct_change().rolling(window=16).mean()

    # Initialize the position series
    positions = pd.Series(0, index=df.index)

    # Iterate over the DataFrame
    for i in range(len(df)):
        if i < 15:
            # Warm-up period
            positions[i] = 0
        else:
            # Check if RSI(16) is defined
            if np.isfinite(df['RSI_16'].iloc[i]):
                # Go long when RSI(16) < 28 and not long
                if df['RSI_16'].iloc[i] < 28 and positions.iloc[i-1] == 0:
                    positions.iloc[i] = 1
                # Go short when RSI(16) > 72 and not short
                elif df['RSI_16'].iloc[i] > 72 and positions.iloc[i-1] == 0:
                    positions.iloc[i] = -1
                # Exit to flat when RSI(16) > 52
                elif df['RSI_16'].iloc[i] > 52:
                    positions.iloc[i] = 0
                # Keep the current position otherwise
                else:
                    positions.iloc[i] = positions.iloc[i-1]

    return positions

