    # Define the breakout logic
    for i in range(len(df)):
        if i < 29:
            # Warm-up period
            positions[i] = 0
        else:
            middle = df['SMA_30'].iloc[i]
            upper = middle + 2.75 * df['PSTD_30'].iloc[i]
            lower = middle - 2.75 * df['PSTD_30'].iloc[i]

